        'slack_blurb' => 'Slack चॅनेलमधील संदेशाचे तिकीट बनवा आणि थ्रेड सोडल्याशिवाय इनबॉक्समधून त्याला उत्तर द्या.',
        'ms365_blurb' => 'Entra ID मधील लोक, गट आणि मॅनेजर, तसेच Intune मधील डिव्हाइसेस, त्यांचे वापरकर्ते आणि अ‍ॅप्स - FreeITSM तुमच्या Microsoft टेनंटमधून जे वाचते ते.',
