        'ms365_open_intune_conn' => 'कनेक्शन',
        'ms365_open_intune_import' => 'आयात',
        'zabbix_blurb' => 'मॉनिटरिंग समस्या आपोआप इन्सिडेंट उघडतात, पुनरावृत्ती त्यात जोडली जाते आणि रिकव्हरी त्यांचे निराकरण करतात.',
        'zabbix_intro' => 'Zabbix ला एखादी समस्या आढळल्यास - डिस्क भरत आहे, सर्व्हर उत्तर देत नाही - तो इथे एक इन्सिडेंट नोंदवतो, जो CMDB मधील त्या सर्व्हरशी जोडलेला असतो. त्याने तीच समस्या पुन्हा कळवली तर ती त्याच तिकिटावर जाते. समस्या दूर झाली की तिकिटाचे निराकरण होते.',
        'zabbix_direction' => 'Zabbix FreeITSM ला कॉल करतो - FreeITSM कधीही Zabbix शी कनेक्ट होत नाही, त्यामुळे त्याला Zabbix चा पत्ता किंवा Zabbix पासवर्ड लागत नाही. Zabbix ला लागणारे सर्व काही खाली आहे.',
        'zabbix_not_ready' => 'आधी सिस्टम → Database Verification चालवा: हे इंटिग्रेशन आपला इव्हेंट लॉग ज्या टेबलमध्ये ठेवते ते तयार करते.',
        'zabbix_connect' => 'Zabbix कनेक्ट करा',
        'zabbix_connect_body' => 'Zabbix प्रत्येक अलर्ट सिक्रेट टोकनसह खालील पत्त्यावर पाठवतो. Zabbix मध्ये Alerts → Media types → Create media type वर जा, Webhook निवडा, नाव FreeITSM ठेवा, खालील पॅरामीटर्स आणि स्क्रिप्ट पेस्ट करा, मग ते एका वापरकर्त्याला आणि Alerts → Actions → Trigger actions अंतर्गत एका action ला जोडा. Action मध्ये "Recovery operations" टिक करा, नाहीतर तिकिटांचे निराकरण कधीच होणार नाही.',
        'zabbix_endpoint' => 'FreeITSM चा पत्ता (हा Zabbix ला द्या)',
        'zabbix_import' => 'सर्वात जलद: Zabbix मध्ये इम्पोर्ट करा',
        'zabbix_import_body' => 'सर्व भरलेला मीडिया टाइप डाउनलोड करा - वरील पत्ता, तुमचा टोकन, स्क्रिप्ट आणि तीन मेसेज टेम्पलेट्स - मग Zabbix मध्ये Alerts → Media types → Import वर जा आणि फाइल निवडा. त्यानंतर तो एका वापरकर्त्याला द्या आणि action जोडा (मार्गदर्शकातील चरण 4).',
        'zabbix_import_download' => 'Zabbix इम्पोर्टसाठी डाउनलोड करा',
        'zabbix_import_needs_token' => 'आधी टोकन तयार करा - फाइलमध्ये तो असतो.',
        'zabbix_by_hand' => 'किंवा हाताने सेट करा',
        'zabbix_token' => 'टोकन',
        'zabbix_token_none' => 'अद्याप टोकन नाही - इंटिग्रेशन चालू करण्यासाठी एक तयार करा.',
        'zabbix_token_make' => 'टोकन तयार करा',
        'zabbix_token_rotate' => 'नवीन टोकन',
        'zabbix_rotate_confirm' => 'नवीन टोकन तयार करायचा? जुना लगेच काम करणे थांबवतो, त्यामुळे तुम्ही नवीन टोकन त्याच्या मीडिया टाइपमध्ये पेस्ट करेपर्यंत Zabbix अयशस्वी होईल.',
        'zabbix_params' => 'मीडिया टाइप पॅरामीटर्स',
        'zabbix_params_hint' => 'नवीन webhook साठी Zabbix भरतो ते पॅरामीटर्स (URL, HTTPProxy, To, Subject, Message) हटवा - ते त्याच्या उदाहरण स्क्रिप्टचे आहेत, या स्क्रिप्टचे नाहीत. मग इथली प्रत्येक ओळ एक पॅरामीटर म्हणून जोडा: डावीकडे नाव, उजवीकडे मूल्य. तुमचा Zabbix सर्व्हर FreeITSM पर्यंत फक्त प्रॉक्सीमार्फत पोहोचू शकत नसेल तर http_proxy रिकामा राहतो. ब्रेसेसमधील मूल्ये Zabbix मॅक्रो आहेत - ती जशी आहेत तशीच ठेवा. url ओळ प्रत्येक तिकिटाला Zabbix मधील समस्येची परतीची लिंक देते; त्यासाठी मॅक्रो {$ZABBIX.URL} तुमच्या Zabbix वेब पत्त्यावर सेट असणे आवश्यक आहे (Zabbix: Administration → Macros). ते नसेल तर तिकिटांना फक्त लिंक नसते.',
        'zabbix_script' => 'मीडिया टाइप स्क्रिप्ट',
        'zabbix_copy' => 'कॉपी',
        'zabbix_copied' => 'कॉपी केले.',
        'zabbix_reach_hint' => 'Zabbix अलर्ट कुठे पाठवेल. हे तुमच्या सार्वजनिक बेस URL पासून सुरू होते; Zabbix त्याच सर्व्हरवर किंवा नेटवर्कवर असल्यास FreeITSM पर्यंतचा त्याचा मार्ग वेगळा असू शकतो - या मशीनवरील Docker मधील Zabbix साठी http://host.docker.internal/ आणि उरलेला मार्ग. इथे बदला आणि पॅरामीटर्स व डाउनलोड त्यानुसार बदलतात.',
        'zabbix_tickets' => 'तो नोंदवत असलेले इन्सिडेंट',
        'zabbix_requester' => 'म्हणून नोंदवले',
