        'zabbix_company_hint' => 'सर्व्हर CMDB मध्ये नसेल किंवा त्याच्या CMDB आयटमला कंपनी नसेल तेव्हा वापरली जाते. CMDB मध्ये असलेला सर्व्हर त्याच्या स्वतःच्या कंपनीकडे जातो.',
        'zabbix_team' => 'संघ',
