        'zabbix_priority_map' => 'तीव्रता → प्राधान्य',
        'zabbix_priority_hint' => 'प्रत्येक Zabbix तीव्रतेसाठी नवीन इन्सिडेंटला कोणते प्राधान्य मिळते.',
        'zabbix_resolve' => 'समस्या दूर झाल्यावर',
