        'zabbix_recovery' => 'रिकव्हरी',
        'zabbix_test' => 'करून पहा',
        'zabbix_test_body' => 'इंटिग्रेशनमधून एक चाचणी समस्या पाठवते, Zabbix च्या खऱ्या अलर्टप्रमाणेच हाताळली जाते: तुमच्या सेटिंग्जनुसार इन्सिडेंट नोंदवला जातो, आणि मग त्याचे निराकरण होताना पाहण्यासाठी तुम्ही त्याची रिकव्हरी पाठवू शकता. चाचणी इन्सिडेंट चाचणी म्हणून शीर्षक देऊन राहतो, म्हणजे खरा कसा दिसतो ते तुम्हाला दिसते - इतर कोणत्याही तिकिटाप्रमाणे तो बंद करा.',
        'zabbix_test_limit' => 'ही FreeITSM ची बाजू तपासते. तुमचा Zabbix सर्व्हर FreeITSM पर्यंत पोहोचू शकतो का ही दुसरी बाजू आहे: ती Zabbix मधील मीडिया टाइपवरील Test बटणाने तपासा.',
