        'msteams_blurb' => 'तुमच्या Teams चॅनेलमध्ये कार्ड म्हणून सर्व्हिस डेस्क अलर्ट - तातडीची तिकिटे, SLA उल्लंघन, प्रत्येक संघासाठी तिकिटे - तिकिटाकडे थेट नेणाऱ्या बटणासह.',
        'msteams_intro' => 'सर्व्हिस डेस्क अलर्ट Microsoft Teams चॅनेलमध्ये कार्ड म्हणून पोस्ट करा, प्रत्येकासह Open in FreeITSM बटण. प्रत्येक चॅनेलला कशाबद्दल कळवायचे ते टिक करा: तातडीची तिकिटे, SLA इशारे आणि उल्लंघन, त्याच्या संघांची तिकिटे, स्टेटस पेज इन्सिडेंट, प्रलंबित मंजुऱ्या.',
        'msteams_not_ready' => 'आधी सिस्टम → Database Verification चालवा: हे अलर्ट ज्या टेबल्समध्ये ठेवले जातात ती तयार करते.',
        'msteams_bot_h' => 'Teams चॅट बॉट',
