        'msteams_bot_count' => '{n} Teams बॉट चॅनेल सेट केले.',
        'msteams_bot_link' => 'मेसेजिंग सेटिंग्ज उघडा',
        'msteams_how_h' => 'चॅनेलचा webhook पत्ता मिळवा',
        'msteams_how_body' => 'Teams मध्ये चॅनेल उघडा, त्याच्या नावाशेजारील … क्लिक करा, मग Workflows. "Post to a channel when a webhook request is received" निवडा, चरणांचे अनुसरण करा आणि शेवटी मिळणारा पत्ता कॉपी करा. तो खाली एका चॅनेलमध्ये पेस्ट करा. हा पत्ता पासवर्डसारखा काम करतो: ज्याच्याकडे तो आहे तो त्या चॅनेलवर पोस्ट करू शकतो, म्हणून तो एन्क्रिप्ट करून साठवला जातो आणि पुन्हा कधीही दाखवला जात नाही.',
