        'threecx_blurb' => 'उत्तर देण्यापूर्वी कोण कॉल करत आहे ते पहा, प्रत्येक कॉल कॉलरच्या तिकिटावर ठेवा आणि एका क्लिकने नंबर डायल करा.',
        'threecx_intro' => 'कॉल वाजला की 3CX FreeITSM ला विचारतो की नंबर कोणाचा आहे आणि कॉलरचे नाव दाखवतो - आणि विश्लेषकासाठी त्यांचे तिकीट उघडतो. कॉल संपला की तो त्या तिकिटावर नोंदवला जातो, कॉल घेणाऱ्या विश्लेषकाच्या नावाने. तिकिटांवरील आणि लोकांचे फोन नंबरही 3CX मार्फत डायल करता येतात.',
        'threecx_direction' => '3CX FreeITSM ला कॉल करतो - FreeITSM कधीही 3CX शी कनेक्ट होत नाही, त्यामुळे त्याला तुमच्या फोन सिस्टमचा पत्ता किंवा 3CX पासवर्ड लागत नाही. 3CX ला लागणारे सर्व काही खालील टेम्पलेटमध्ये आहे.',
