        'tika_intro' => 'FreeITSM ला दस्तऐवज वाचणाऱ्या सेवेकडे निर्देशित करते. Word, Excel, PowerPoint आणि साधा मजकूर फाइल्समध्ये याशिवायही शोध घेता येतो; FreeITSM स्वतः वाचू शकत नाही असे फॉरमॅट Tika जोडते.',
