        'tika_security_body' => 'Tika ला पासवर्ड नाही आणि कोणत्याही प्रकारचे ऑथेंटिकेशन नाही: त्याच्यापर्यंत पोहोचू शकणारे कोणीही त्याला पाठवलेली कोणतीही फाइल वाचवू शकते. ते असे चालवा की फक्त हा सर्व्हरच त्याच्याशी बोलू शकेल — 127.0.0.1 वर बांधलेले, किंवा खासगी कंटेनर नेटवर्कवर — आणि त्याचा पोर्ट इंटरनेटवर कधीही उघडा ठेवू नका.',
        'tika_connection' => 'कनेक्शन',
        'tika_url_label' => 'पत्ता',
        'tika_url_hint' => 'उदाहरणार्थ http://127.0.0.1:9998. दस्तऐवज वाचणे बंद करण्यासाठी हे रिकामे ठेवा; PDF फक्त न वाचता येणाऱ्या म्हणून दाखवल्या जातील.',
        'tika_timeout_label' => 'टाइमआउट (सेकंद)',
