        'tika_running' => 'एक चालवणे',
        'tika_running_body' => 'FreeITSM Tika इन्स्टॉल किंवा व्यवस्थापित करत नाही. ते तुम्हाला सोयीच्या ठिकाणी स्वतः चालवा आणि त्याचा पत्ता वर टाका. Docker सोबत हा एकच कमांड आहे:',
        'tika_image_note' => '-full इमेज वापरा. लहान इमेजमध्ये अक्षर ओळख नाही, त्यामुळे स्कॅन केलेले दस्तऐवज रिकामे येतील.',
        'slack_workspaces' => 'Slack वर्कस्पेसेस',
        'slack_workspaces_desc' => 'प्रत्येक एक म्हणजे तुम्ही तुमच्या स्वतःच्या वर्कस्पेसमध्ये इन्स्टॉल केलेले Slack अॅप. FreeITSM तुमचा Slack ट्रॅफिक कधीही पाहत नाही — अॅप थेट या सर्व्हरशी बोलते.',
        'slack_col_channel' => 'निरीक्षण',
        'slack_any_channel' => 'आमंत्रित केलेले कोणतेही चॅनेल',
        'slack_empty' => 'अद्याप कोणतीही Slack वर्कस्पेस नाही. एक जोडा, मग Slack मधून त्याचे अॅप घ्या.',
        'slack_needs_setup' => 'सेटअप आवश्यक',
        'slack_add_title' => 'Slack वर्कस्पेस जोडा',
        'slack_edit_title' => 'Slack वर्कस्पेस संपादित करा',
        'slack_name_hint' => 'फक्त या यादीत वापरले जाते, आणि तुम्ही तयार केलेल्या Slack अॅपचे नाव म्हणून.',
        'slack_name_required' => 'या वर्कस्पेसला नाव द्या.',
        'slack_unchanged' => 'बदललेले नाही — ठेवण्यासाठी रिकामे ठेवा',
        'slack_bot_token' => 'Bot user OAuth token',
        'slack_bot_token_hint' => 'तुमच्या Slack अॅपमधून, OAuth &amp; Permissions अंतर्गत. xoxb- ने सुरू होते. अॅप इन्स्टॉल केल्यानंतर ते मिळते, म्हणून पहिल्या जतनाच्या वेळी ते रिकामे ठेवा.',
        'slack_signing_secret' => 'Signing secret',
        'slack_signing_secret_hint' => 'तुमच्या Slack अॅपमधून, Basic Information अंतर्गत. संदेश खरोखर Slack कडून आला हे FreeITSM याद्वारे सिद्ध करते, त्यामुळे हे सेट होईपर्यंत काहीही स्वीकारले जात नाही.',
        'slack_watch_channel' => 'फक्त हे चॅनेल पहा',
        'slack_watch_channel_hint' => 'C08ABCDEF सारखा Slack चॅनेल ID. अॅपला आमंत्रित केलेल्या प्रत्येक चॅनेलमधून तिकीट बनवण्यासाठी रिकामे ठेवा — व्यस्त चॅनेलवर याचा अर्थ प्रत्येक संदेशाला एक तिकीट, म्हणून बहुतेक लोक इथे एक मदत चॅनेल नाव देतात.',
        'slack_company_shared' => 'सामायिक — प्रेषकानुसार ठरवा',
        'slack_company_hint' => 'या वर्कस्पेसला एका कंपनीशी बांधा, किंवा ती सामायिक ठेवा आणि प्रेषकाला ठरवू द्या.',
        'slack_delete_confirm' => 'Slack वर्कस्पेस “{name}” हटवायची? त्यातून आधीच नोंदवलेल्या तिकिटांचा इतिहास राहतो; फक्त नवीन संदेश येणे थांबते.',
        'slack_diag_title' => 'Slack आरोग्य तपासणी',
        'slack_diag_desc' => 'शांतपणे चुकीचे असू शकणारे सर्व काही तपासते — फक्त टोकन चालते की नाही एवढेच नाही. प्रत्येक निकाल त्यावर काय करायचे ते सांगतो.',
        'slack_diag_running' => 'तपासत आहे — हे Slack शी आणि तुमच्या स्वतःच्या सार्वजनिक पत्त्याशी बोलते, म्हणून काही सेकंद द्या…',
        'slack_diag_rerun' => 'पुन्हा चालवा',
        'slack_diag_all_ok' => 'सर्व काही ठीक आहे. निरीक्षण केलेल्या Slack चॅनेलमध्ये पोस्ट केलेले संदेश तिकिटे बनतील, आणि उत्तरे थ्रेडमध्ये परत जातील.',
        'slack_diag_some_warn' => 'चालू आहे, पण जाणून घेण्यासारखे काहीतरी आहे. खालीलपैकी काहीही तिकिटे येण्यापासून रोखत नाही, पण वाचण्यासारखे आहे.',
        'slack_diag_some_fail' => 'काहीतरी चुकले आहे आणि संदेश येणार नाहीत. खाली अयशस्वी तपासण्या काय करायचे ते सांगतात.',
        'slack_app_title' => 'Slack अॅप',
        'slack_copy_manifest' => 'मॅनिफेस्ट कॉपी करा',
        'slack_scopes_heading' => 'अॅपला काय करण्याची परवानगी आहे',
        'slack_scopes_desc' => 'अॅप मंजूर करताना तुमच्या Slack ॲडमिनला ही यादी दिसेल. यातील काहीही त्याला चॅनेल तयार करू देत नाही, लोकांना आमंत्रित करू देत नाही किंवा आमंत्रित न केलेल्या ठिकाणी पोस्ट करू देत नाही.',
        'slack_step1' => 'Slack मध्ये, <strong>api.slack.com/apps</strong> वर जा आणि <strong>Create New App → From a manifest</strong> निवडा. सर्व्हिस डेस्क ज्यात हवा ती वर्कस्पेस निवडा.',
        'slack_step2' => 'हा मॅनिफेस्ट पेस्ट करा. तो नाव, परवानग्या आणि Slack संदेश पाठवते तो पत्ता सेट करतो, त्यामुळे हाताने काहीही टिक करावे लागत नाही.',
        'slack_step3' => '<strong>Install to Workspace</strong> वर क्लिक करा आणि मंजूर करा. मग <strong>Bot User OAuth Token</strong> आणि <strong>Signing Secret</strong> कॉपी करून इथल्या संपादन फॉर्ममध्ये परत टाका — Slack टोकन पुन्हा दाखवणार नाही. <strong>Slack ने पिवळा &ldquo;Reinstall to Workspace&rdquo; बॅनर दाखवला तर, आधी त्यावर क्लिक करा</strong> — नाहीतर टोकनमध्ये बहुतेक परवानग्या नसतात आणि तिकिटे प्रेषकाच्या नावाशिवाय येतात.',
        'slack_step4' => 'खालील विनंती URL <strong>Event Subscriptions</strong> अंतर्गत Slack दाखवते त्याशी जुळतो का ते तपासा. अॅप जतन करताच Slack तो पडताळते, म्हणून हा सर्व्हर इंटरनेटवरून पोहोचण्याजोगा असणे आवश्यक आहे.',
        'slack_step5' => 'Slack मध्ये, अॅपला ज्या चॅनेलवर लक्ष ठेवायचे आहे त्यात आमंत्रित करा: <strong>/invite @YourApp</strong>. ते ज्या चॅनेलमध्ये नाही ते वाचू शकत नाही.',
    ],
