        'warning' => '<strong>हे सुरू करण्यापूर्वी वाचा.</strong> घटनांची शीर्षके तुमच्या संघासाठी लिहिलेली असतात, ग्राहकांसाठी नाही &mdash; अंतिम वापरकर्ते ती वाचू लागण्यापूर्वी तुमच्या घटनांमध्ये काय लिहिले आहे ते तपासा. फक्त स्पष्टपणे <strong>बाह्य</strong> म्हणून चिन्हांकित केलेले अपडेट्सच दाखवले जातात; हे फीचर येण्यापूर्वी लिहिलेले सर्व काही अंतर्गत आहे आणि अंतर्गतच राहते.',
        'panel_heading' => 'पोर्टल काय दाखवते',
        'enable_label' => 'सेल्फ-सर्व्हिस पोर्टलमध्ये घटना आणि त्यांचे बाह्य अपडेट्स दाखवा',
        'enable_hint' => 'डीफॉल्टनुसार बंद. हे बंद असताना पोर्टल फक्त सेवेची स्थिती दाखवते &mdash; पूर्वीप्रमाणेच.',
        'mode_open' => 'फक्त सध्या जे घडत आहे ते',
        'mode_open_desc' => 'सर्वात स्वच्छ पृष्ठ. खंडन निराकरण होताच अदृश्य होते, त्यामुळे तासाभरापूर्वी बाधित झालेल्या व्यक्तीला ते दुरुस्त झाल्याची खात्री मिळत नाही.',
        'mode_recent' => 'सध्या जे घडत आहे, तसेच गेल्या इतक्या कालावधीत निराकरण झालेले सर्व',
        'mode_recent_days' => 'दिवस',
        'mode_recent_desc' => 'शिफारस केलेले. निराकरण झालेली नोंद स्थिती पृष्ठावरील सर्वात आश्वासक गोष्ट असते, आणि बहुतेक लोक स्थिती पृष्ठ म्हणजे हेच समजतात.',
