        'ab_desc' => 'डीफॉल्टनुसार बंद. यामुळे तुमचे ग्राहक तुमच्या अ‍ॅड्रेस बुकमध्ये लिहू शकतात, त्यामुळे हा निर्णय तुमचा आहे. फक्त <strong>बदल परत लिहा</strong> सुरू असलेल्या अ‍ॅड्रेस बुकमध्येच लिहिले जाते. त्यांचा बदल अ‍ॅड्रेस बुकने स्वीकारल्यानंतरच जतन केला जातो, आणि प्रत्येक लेखन अ‍ॅड्रेस बुकच्या लेखन नोंदीत असते.',
