        'status_on_body' => '{host} साठीचे प्रमाणपत्र वापरात आहे आणि {date} पर्यंत वैध आहे.',
        'status_broken_title' => 'प्रमाणपत्र फाइल्स जुळत नाहीत',
        'status_broken_body' => 'डिस्कवरील प्रमाणपत्र आणि त्याची की एकमेकांशी जुळत नाहीत, म्हणून कंटेनर साध्या HTTP वरच राहत आहे. नवीन जोडी तयार करण्यासाठी खाली तयार करा दाबा.',
        'status_restart_title' => 'पूर्ण करण्यासाठी कंटेनर रीस्टार्ट करा',
        'status_restart_body' => '{host} साठीचे प्रमाणपत्र तयार आहे, पण कंटेनर अजूनही त्याशिवाय चालू आहे. तुमची docker-compose.yml असलेल्या फोल्डरमध्ये {cmd} चालवा.',
        'form_heading' => 'प्रमाणपत्र',
        'browsing_at' => 'तुम्ही FreeITSM ला {address} वर पोहोचत आहात.',
        'host_label' => 'लोक टाइप करतील ते नाव',
        'host_help' => 'उदाहरणार्थ freeitsm.internal. .internal ने संपणारे नाव कंपनीच्या नेटवर्कमध्ये वापरण्यास सुरक्षित आहे. .local टाळा, कारण काही PC ते इतर गोष्टींसाठी राखून ठेवतात.',
        'ip_label' => 'सर्व्हर IP पत्ता',
        'ip_help' => 'Docker चालवणाऱ्या मशीनचा पत्ता, जसा PC ला दिसतो. तुम्ही हे पृष्ठ IP ने उघडल्यास तो तुमच्या अ‍ॅड्रेस बारमधून भरला जातो. ऐच्छिक, पण त्यामुळे HTTPS IP ने देखील चालते.',
        'generate' => 'तयार करा',
        'generating' => 'तयार होत आहे...',
        'local_warning' => '.local ने संपणारी नावे नेटवर्कवरील इतर डिव्हाइसशी टकरावू शकतात. त्याऐवजी .internal वापरण्याचा विचार करा.',
        'confirm_new_ca' => 'नाव किंवा IP बदलल्याने नवीन अधिकारी प्रमाणपत्र तयार होते. जुन्यावर विश्वास ठेवणाऱ्या प्रत्येक PC वर नवीन इन्स्टॉल करावे लागेल. सुरू ठेवायचे?',
        'err_invalid_host' => 'हे वैध नाव नाही. फक्त अक्षरे, अंक, हायफन आणि बिंदू वापरा, उदाहरणार्थ freeitsm.internal.',
        'err_invalid_ip' => 'हा वैध IP पत्ता नाही.',
        'err_not_persisted' => 'आधी या पृष्ठाच्या वरील Docker बदल करा.',
        'err_generic' => 'प्रमाणपत्र तयार करता आले नाही: {error}',
        'steps_heading' => 'पुढे काय करायचे',
        'step_dns_title' => 'नाव सर्व्हरकडे निर्देशित करा',
        'step_dns_body' => 'PC ना कळले पाहिजे की {host} म्हणजे {ip}. सर्वोत्तम मार्ग म्हणजे तुमच्या नेटवर्कच्या DNS सर्व्हरवर DNS रेकॉर्ड (Windows डोमेनवर, DNS Manager मध्ये; लहान नेटवर्कवर, बहुतेकदा राउटरमध्ये):',
        'step_dns_record' => 'प्रकार A, नाव {host}, पत्ता {ip}',
        'step_dns_hosts' => 'DNS सर्व्हर नसल्यास, प्रत्येक PC वरील hosts फाइलमध्ये ही ओळ जोडा (Windows वर {path}, Mac वर {path_mac}):',
        'step_dns_no_ip' => 'तयार करायचा नेमका रेकॉर्ड पाहण्यासाठी वर सर्व्हर IP पत्ता भरा.',
        'step_ca_title' => 'प्रत्येक PC वर अधिकारी प्रमाणपत्र इन्स्टॉल करा',
        'step_ca_body' => 'यामुळे PC ना प्रमाणपत्रावर विश्वास ठेवण्यास सांगितले जाते. हे प्रत्येक PC वर एकदाच करावे लागते, आणि नाव किंवा IP बदलल्यासच पुन्हा.',
        'download' => 'डाउनलोड',
        'step_ca_windows' => 'Windows: फाइलवर डबल-क्लिक करा, Install Certificate निवडा, Local Machine निवडा, मग Place all certificates in the following store निवडा, आणि Trusted Root Certification Authorities निवडा.',
        'step_ca_gpo' => 'डोमेनवरील अनेक Windows PC: Group Policy मध्ये, Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities येथे फाइल एकदा इम्पोर्ट करा. Intune ते Trusted certificate प्रोफाइल म्हणून पाठवू शकते.',
        'step_ca_mac' => 'Mac: Keychain Access मध्ये जोडण्यासाठी फाइलवर डबल-क्लिक करा, तिथे ती उघडा आणि When using this certificate ला Always Trust वर सेट करा.',
        'step_ca_firefox' => 'Windows वरील Firefox आपोआप Windows प्रमाणपत्रे वापरतो. तरीही चेतावणी आल्यास, about:config मध्ये security.enterprise_roots.enabled true वर सेट करा.',
        'step_ca_safe' => 'हा अधिकारी फक्त {host} ची हमी देऊ शकतो, इतर कशाचीही नाही, त्यामुळे तो इन्स्टॉल केल्याने तो इतर कोणत्याही वेबसाइटचे ढोंग करू शकत नाही.',
        'step_restart_title' => 'कंटेनर रीस्टार्ट करा',
        'step_restart_body' => 'तुमची docker-compose.yml असलेल्या फोल्डरमध्ये {cmd} चालवा.',
        'step_restart_done' => 'पूर्ण: कंटेनर हे प्रमाणपत्र वापरत आहे.',
        'step_open_title' => 'FreeITSM HTTPS वरून उघडा',
        'step_open_body' => '{url} वर जा. ते लोड न झाल्यास, तुमची docker-compose.yml पोर्ट 443 प्रकाशित करते का ते तपासा (मानक फाइल ते 8443 वर मॅप करते). तुम्ही ते बदलले असल्यास, तुमचा पोर्ट वापरा.',
        'proxy_heading' => 'रिव्हर्स प्रॉक्सीच्या मागे',
        'proxy_intro' => 'FreeITSM समोर रिव्हर्स प्रॉक्सी, लोड बॅलन्सर किंवा Cloudflare Tunnel असल्यास, प्रत्येक विनंती प्रॉक्सीकडून FreeITSM पर्यंत पोहोचते. कोणता पत्ता प्रॉक्सी आहे हे तुम्ही FreeITSM ला सांगितले नाही, तर ते सर्वांसाठी प्रॉक्सीचाच पत्ता नोंदवते: रिपोर्टिंग → लॉग्समध्ये, ऑडिट ट्रेलमध्ये आणि API key कोणते पत्ते परवानगी देते ते तपासताना.',
        'proxy_off_title' => 'बंद',
        'proxy_off_body' => 'FreeITSM प्रत्येक कनेक्शन ज्या पत्त्यावरून येते तो पत्ता नोंदवते. लोक थेट FreeITSM ला कनेक्ट होत असतील तर ते योग्य आहे, आणि प्रॉक्सीच्या मागे चुकीचे - तुमच्याकडे कोणते आहे ते पाहण्यासाठी खालील चाचणी वापरा.',
        'proxy_on_title' => 'चालू',
        'proxy_on_body' => 'खरा पत्ता {header} हेडरमधून घेतला जातो, परंतु फक्त {list} कडून येणाऱ्या विनंत्यांवर.',
        'proxy_refused_title' => 'सेट केले आहे, पण लागू नाही',
        'proxy_refused_body' => 'TRUSTED_PROXIES {list} वर सेट आहे, परंतु कंटेनर सुरू होताना ते नाकारले गेले, त्यामुळे FreeITSM प्रत्येक कनेक्शन ज्या पत्त्यावरून येते तो पत्ता नोंदवते. कारण पाहण्यासाठी {cmd} चालवा.',
        'proxy_wide_title' => 'चेतावणी: ही सेटिंग खूप व्यापक आहे',
        'proxy_wide_body' => '{ranges} एकापेक्षा जास्त प्रॉक्सी व्यापते. त्यातील प्रत्येक मशीन हवा तो पत्ता असल्याचा दावा करू शकते. TRUSTED_PROXIES प्रॉक्सीच्या स्वतःच्या पत्त्यावर बदला आणि कंटेनर रीस्टार्ट करा.',
        'proxy_danger_title' => 'चुकीची सेटिंग काय करते - बदलण्यापूर्वी हे वाचा',
        'proxy_danger_wide' => 'खूप व्यापक - धोकादायक चूक. FreeITSM प्रॉक्सीच्या हेडरमधील पत्त्यावर फक्त तुम्ही यादी केलेल्या पत्त्यांकडून आलेल्या विनंत्यांवरच विश्वास ठेवते, कारण ते हेडर कोणीही लिहू शकते. {example} सारखी रेंज किंवा संपूर्ण Docker नेटवर्क यादीत दिल्यास, त्यातील कोणतेही मशीन हवा तो पत्ता असल्याचा दावा करू शकते: ते साइन-इन लॉग आणि ऑडिट ट्रेलमध्ये खोटा पत्ता टाकू शकते, आणि फक्त ठराविक पत्त्यांना परवानगी देणाऱ्या API key मधून आत शिरू शकते. फक्त प्रॉक्सीचा स्वतःचा पत्ता द्या.',
        'proxy_danger_missing' => 'सेट केलेले नाही, आणि प्रॉक्सी आहे. काहीही बिघडत नाही, पण प्रत्येक साइन-इन आणि प्रत्येक बदल प्रॉक्सीच्या पत्त्यावरून नोंदवला जातो, त्यामुळे लॉग लोकांमध्ये फरक करू शकत नाहीत - आणि API key चे परवानगी दिलेले पत्ते फक्त प्रॉक्सीचेच असू शकतात, ज्यामुळे त्यातून येणाऱ्या कोणालाही प्रवेश मिळतो.',
        'proxy_danger_wrong' => 'चुकीचा पत्ता. हेडर दुर्लक्षित केले जाते, त्यामुळे पुन्हा सर्वजण प्रॉक्सी म्हणून नोंदवले जातात. चाचणी हे लगेच दाखवते.',
        'proxy_how' => 'हे या पृष्ठावर नव्हे तर docker-compose.yml मध्ये सेट केले जाते, आणि कंटेनर रीस्टार्ट झाल्यावर (docker compose up -d) लागू होते:',
        'proxy_how_cf' => 'Cloudflare Tunnel साठी {setting} देखील सेट करा. अनेक प्रॉक्सी: त्यांना स्पेसने वेगळे करा.',
        'proxy_test_heading' => 'चाचणी.',
        'proxy_test_intro' => 'FreeITSM ने आत्ताच तुमच्यासाठी कोणता पत्ता नोंदवला आणि त्याचा अर्थ काय ते दाखवते. काहीही बदलत नाही.',
        'proxy_test' => 'चाचणी',
        'proxy_testing' => 'तपासत आहे...',
        'proxy_test_failed' => 'चाचणी चालवता आली नाही.',
        'proxy_recorded' => 'FreeITSM ने तुमचा पत्ता असा नोंदवला',
        'verdict_direct' => 'तुम्ही थेट FreeITSM ला कनेक्ट होत आहात - कोणतेही प्रॉक्सी हेडर आले नाही - त्यामुळे सेट करण्यासारखे काही नाही. समोर प्रॉक्सी आहे हे तुम्हाला माहीत असल्यास, ते हेडर जोडत नाही: त्याच्या सेटिंग्ज तपासा.',
        'verdict_off_proxy' => 'FreeITSM समोर प्रॉक्सी आहे (या विनंतीत {headers} होते), आणि FreeITSM सर्वांसाठी प्रॉक्सीचा पत्ता, {ip}, नोंदवत आहे. खरे पत्ते नोंदवण्यासाठी, docker-compose.yml मधील अ‍ॅपच्या एन्व्हायर्नमेंटमध्ये हे जोडा:',
        'proxy_suggest_then' => 'FreeITSM ला दिसतो तसा हा प्रॉक्सीचा पत्ता आहे - तो एकटाच द्या, त्यापेक्षा व्यापक काही नाही. मग docker compose up -d चालवा आणि पुन्हा चाचणी करा.',
        'verdict_working' => 'चालू आहे: हा पत्ता प्रॉक्सीच्या हेडरमधून आला. तो खरोखर तुमच्या संगणकाचा पत्ता आहे का ते तपासा - Windows वर ipconfig तो दाखवतो; तुमच्या नेटवर्कबाहेरून, तुमचा सार्वजनिक पत्ता. तो प्रॉक्सीचा पत्ता किंवा 127.0.0.1 दाखवत असल्यास, काहीतरी चुकले आहे.',
        'verdict_too_wide' => 'सुरक्षित नाही: तुमचा स्वतःचा पत्ता, {ip}, FreeITSM प्रॉक्सी म्हणून ज्या रेंजवर विश्वास ठेवते तिच्या आत आहे, त्यामुळे FreeITSM तुम्हाला आणि प्रॉक्सीला वेगळे ओळखू शकत नाही - आणि त्या रेंजमधील इतर कोणीही कोणताही पत्ता असल्याचा दावा करू शकतो. TRUSTED_PROXIES प्रॉक्सीच्या स्वतःच्या पत्त्यावर बदला आणि कंटेनर रीस्टार्ट करा.',
        'verdict_still_proxy' => 'चालू नाही: नोंदवलेला पत्ता प्रॉक्सीचाच आहे, म्हणजे प्रॉक्सी {header} हेडर पाठवत नाही. प्रॉक्सीला {header} जोडायला लावा, किंवा TRUSTED_PROXY_HEADER तो पाठवत असलेल्या हेडरवर सेट करा.',
        'verdict_refused' => 'सेटिंग लागू नाही (वर पहा), त्यामुळे FreeITSM प्रत्येक कनेक्शन ज्या पत्त्यावरून येते तो पत्ता नोंदवते. आधी सेटिंग दुरुस्त करा, मग पुन्हा चाचणी करा.',
        'proxy_headers_seen' => 'या विनंतीवरील प्रॉक्सी हेडर:',
        'proxy_headers_none' => 'या विनंतीवर कोणतेही प्रॉक्सी हेडर नाहीत.',
    ],
    'modules' => [
        'title' => 'मॉड्यूल प्रवेश',
        'subtitle' => 'प्रत्येक विश्लेषकाला मुख्य स्क्रीनवर आणि नेव्हिगेशनमध्ये कोणते मॉड्यूल दिसतील ते नियंत्रित करा',
        'info_text' => 'डीफॉल्टनुसार सर्व विश्लेषकांना प्रत्येक मॉड्यूलचा प्रवेश असतो. विश्लेषकाला विशिष्ट मॉड्यूलपुरते मर्यादित करण्यासाठी {all_access} बंद करा. System मॉड्यूल अक्षम करता येत नाही.',
