        'subtitle' => 'विश्लेषकांची शेड्यूल केलेली तिकिटे ते प्रत्यक्ष वापरत असलेल्या दिनदर्शिकांमध्ये ठेवा, आणि त्यांना सबस्क्रिप्शन लिंक प्रकाशित करता येईल का ते ठरवा.',
        'needs_db' => 'आधी डेटाबेस अद्यतन आवश्यक आहे',
        'needs_db_desc' => 'सिस्टम → डेटाबेस पडताळणी चालवा, मग या पृष्ठावर परत या.',
