        'people_desc_caldav' => 'प्रत्येक विश्लेषक CalDAV सर्व्हरवर साइन इन करतो आणि प्राधान्ये मध्ये स्वतःची दिनदर्शिका निवडतो. प्रशासक त्यांच्यासाठी ती निवडू शकत नाही, कारण तिच्यापर्यंत पोहोचणारा पासवर्ड फक्त विश्लेषकाकडे असतो.',
