        'perm_title' => 'हे चालण्यापूर्वी',
        'perm_body' => 'अ‍ॅप नोंदणीला <strong>Application</strong> परवानगी म्हणून <strong>Calendars.ReadWrite</strong> हवी (Delegated नव्हे — Azure मध्ये त्या वेगळ्या याद्या आहेत), आणि अॅडमिन संमती दिलेली असावी. लक्षात ठेवा की ही परवानगी FreeITSM ला <strong>टेनंटमधील प्रत्येक मेलबॉक्समध्ये</strong> लिहू देते. तुम्हाला इतके द्यायचे नसेल, तर Exchange Online मधील Application Access Policy वापरून अ‍ॅपला तुमच्या विश्लेषकांच्या मेल-सक्षम सुरक्षा गटापुरते मर्यादित करा.',
