        'notify_url' => 'सूचना URL (ऐच्छिक)',
        'notify_url_note' => 'फक्त शेड्यूल केलेल्या तपासणीवर अवलंबून राहण्यासाठी रिकामे सोडा, जे अगदी चांगले आहे &mdash; बदल तेव्हा काही मिनिटांत येतात. ते भरल्यास Microsoft काही बदलताच FreeITSM ला कळवते, त्यामुळे ते काही सेकंदांत पोहोचते. तो <strong>Microsoft ला इंटरनेटवरून पोहोचता येईल असा HTTPS पत्ता</strong> असावा, जो <code>/api/calendar/graph_notify.php</code> ने संपतो. दोन्ही बाबतीत शेड्यूल केलेला जॉब आवश्यक आहे: तो सबस्क्रिप्शन नूतनीकरण करतो, आणि चुकलेल्या सूचनेमुळे जे हरवले असते ते पकडतो.',
        'notify_suggest' => 'हा पत्ता वापरा',
