        'notify_saved' => 'शेड्यूल केलेला जॉब पुढच्या वेळी चालताना सबस्क्रिप्शन तयार किंवा अद्यतनित करेल.',
        'notify_active' => '{n} सबस्क्रिप्शन सक्रिय',
