        'section_memory_desc' => 'तुम्ही मेनू, होम पृष्ठ किंवा Ctrl+K मधून मॉड्यूल उघडता तेव्हा, त्याच्या मुख्य पृष्ठाऐवजी तुम्ही तेथे शेवटी वापरलेल्या विभागात जा - उदा. मालमत्ता → सर्व्हर्स. विशिष्ट पृष्ठ किंवा नोंदीच्या लिंक्स अगदी तेच उघडतात. या ब्राउझरमध्ये लक्षात ठेवले जाते.',
        'section_memory_label' => 'प्रत्येक मॉड्यूलचा शेवटचा विभाग पुन्हा उघडा',
