        'ipban_heading' => 'IP बंदी',
        'ipban_desc' => 'अस्तित्वात नसलेल्या किंवा लॉक केलेल्या खात्यांवर वारंवार लॉगिन प्रयत्न करणारे IP पत्ते आपोआप बंद करा. प्रत्येक बंदी 24 तास टिकते. प्रत्येक बंदीनंतर मर्यादा 1 ने कमी होते (किमान मर्यादेपर्यंत), ज्यामुळे वारंवार गुन्हा करणाऱ्यांना गैरवापर करणे कठीण होते. बंद करण्यासाठी कमाल प्रयत्न 0 वर सेट करा.',
