        'allowed_extensions_hint' => 'FreeITSM जे सुरक्षित मानते ते सर्व स्वीकारण्यासाठी रिकामे ठेवा, भविष्यातील अद्यतनांनी जोडलेल्या नवीन प्रकारांसह. कमी स्वीकारण्यासाठी, फक्त हव्या असलेल्या एक्स्टेंशन स्वल्पविरामाने वेगळ्या करून लिहा.',
        'allowed_extensions_ph' => 'उदा. pdf, docx, xlsx, png, jpg',
