        'rejected_note' => 'कोणत्याही प्रकारे तिकीट काय झाले आणि का ते सांगते, त्यामुळे त्यांची फाइल कुठे गेली असा प्रश्न कोणाला पडत नाही.',
        'max_attachment' => 'सर्वात मोठे जोडपत्र',
