        'max_total' => 'सर्वात मोठा ईमेल',
        'max_total_hint' => 'एका येणाऱ्या ईमेलवरील सर्व जोडपत्रे एकत्र. 0 म्हणजे वरील मर्यादेपलीकडे कोणतीही मर्यादा नाही.',
        'php_limits' => 'या सर्व्हरवरील PHP ब्राउझर अपलोड प्रति फाइल {upload} आणि प्रति विनंती {post} पर्यंत स्वीकारते (php.ini मधील upload_max_filesize आणि post_max_size), आणि काम करण्यासाठी {memory} मेमरी आहे. PHP ने नाकारलेली फाइल FreeITSM पर्यंत कधीच पोहोचत नाही, त्यामुळे यापेक्षा जास्त मर्यादा फक्त ईमेलसाठी उपयोगी ठरते. समोरील वेब सर्व्हर किंवा प्रॉक्सी (nginx client_max_body_size, IIS maxAllowedContentLength) स्वतःची कमी मर्यादा ठेवू शकतो.',
