        'carddav_allow_create_hint' => 'डीफॉल्टनुसार बंद. हे चालू असल्यास, कोणत्याही अ‍ॅड्रेस बुकमध्ये नसलेल्या व्यक्तीला Tickets आणि Assets मध्ये अ‍ॅड्रेस बुकमध्ये जोडा बटण मिळते, जे येथे त्यांचे कार्ड तयार करते आणि त्यांना जोडते. काहीही लिहिण्यापूर्वी FreeITSM बुकमधील कोणाकडेही त्यांचा ईमेल पत्ता नाही हे तपासते, आणि नंतर नवीन कार्ड हा स्रोत आयात करतो तेच आहे का ते तपासते - तो ज्याने आयात करतो तो टॅग किंवा गट जोडून - आणि नसल्यास ते पुन्हा काढून टाकते.',
        'carddav_write_warning' => 'वर सूचीबद्ध केलेले तपशीलच बदलले जातात, आणि फक्त संपादित होत असलेल्या संपर्कावर. कार्डावरील बाकी सर्व — फोटो, नोंदी, वाढदिवस, पूर्ण पत्ता, गट — जसे आहे तसेच राहते. FreeITSM ने शेवटचे आयात केल्यापासून अ‍ॅड्रेस बुकमध्ये कोणी तोच तपशील बदलला असल्यास, त्यांचा बदल अधिलिखित करण्याऐवजी हा बदल नाकारला जातो.',
