        'subtitle' => 'आउटबाउंड वेबहूक &mdash; <em>वेबहूक पाठवा</em> वर्कफ्लो क्रियेद्वारे रांगेत ठेवलेले &mdash; आपोआप पुन्हा प्रयत्नांसह पार्श्वभूमीत पाठवले जातात, त्यामुळे संथ किंवा बंद एंडपॉइंट तिकिटाला कधीही अडवत नाही. हे पृष्ठ डिलिव्हरी सेट केली आहे का, डिलिव्हरीच्या स्थितीचा आढावा, आणि संपूर्ण नोंद दाखवते जिथे तुम्ही प्रत्येक विनंती, तिचा प्रतिसाद तपासू शकता आणि कोणतीही पुन्हा पाठवू शकता.',
