        'opt_default' => '{label} (डीफॉल्ट)',
        'del_attempts_label' => 'हार मानण्यापूर्वीचे प्रयत्न',
        'del_attempts_one' => '1 प्रयत्न (पुन्हा प्रयत्न नाही)',
        'del_attempts_opt' => '{n} प्रयत्न',
        'del_attempts_help' => 'अयशस्वी प्रयत्नाची पुनरावृत्ती 1 मिनिटानंतर, मग 5 मिनिटे, 15 मिनिटे, 1 तास आणि 6 तासांनी होते, त्यानंतर दर 6 तासांनी. शेवटच्या प्रयत्नानंतर डिलिव्हरी <strong>डेड</strong> म्हणून चिन्हांकित होते आणि <em>रीप्ले</em> ची वाट पाहते. बदल आतापासून रांगेत येणाऱ्या webhooks ना लागू होतो - आधीच रांगेत असलेले सुरू झालेली संख्या राखतात.',
        'del_timeout_label' => 'एंडपॉइंटच्या उत्तराची वाट पहा',
        'del_timeout_opt' => '{n} सेकंद',
        'del_timeout_help' => 'प्रत्येक प्रयत्न अयशस्वी मानण्यापूर्वी किती वेळ थांबतो. फक्त संथ असल्याचे माहीत असलेल्या एंडपॉइंटसाठी वाढवा: वर्कर एका वेळी एकच webhook पाठवतो, त्यामुळे जास्त प्रतीक्षा बाकीची रांग रोखून धरते. वर्कफ्लो संपादकातील <em>टेस्ट पाठवा</em> जास्तीत जास्त 25 सेकंद थांबतो.',
        'del_int_label' => 'पाठवणे मध्येच तुटल्यास',
        'del_int_retry' => 'पुन्हा प्रयत्न करा - एंडपॉइंटला ते दोनदा मिळू शकते',
        'del_int_stop' => 'थांबा, आणि रीप्लेसाठी ठेवा',
        'del_int_help' => 'पाठवण्याच्या मध्येच वर्कर थांबला - सर्व्हर रीस्टार्ट किंवा शेड्यूल्ड टास्क बंद केला - तर एंडपॉइंटला ते मिळाले की नाही हे कोणालाच माहीत नसते. 10 मिनिटांनंतर FreeITSM तो निर्णय घेते: <strong>पुन्हा प्रयत्न करा</strong> त्याला अयशस्वी प्रयत्न मानून वरील वेळापत्रकानुसार पुन्हा प्रयत्न करते; <strong>थांबा</strong> त्याला लगेच डेड चिन्हांकित करते, म्हणजे तुम्ही एंडपॉइंट तपासून स्वतः रीप्ले करू शकता. प्रत्येक पाठवण्यात <code>X-FreeITSM-Delivery</code> हेडर असतो, ज्याचा क्रमांक प्रत्येक प्रयत्नात आणि रीप्लेवर सारखाच असतो, त्यामुळे तुम्ही चालवलेला रिसीव्हर पुनरावृत्ती दुर्लक्षित करू शकतो. Slack आणि Teams सारखी चॅट टूल्स तसे करू शकत नाहीत, आणि संदेश दोनदा दिसेल.',
        'dp_title' => 'डेटा संरक्षण',
        'dp_desc' => 'FreeITSM तुमच्या वेबहूकबद्दल डिस्कवर काय आणि किती काळ ठेवते.',
        'enc_on_title' => 'वेबहूक URL आणि सिग्नेचर सीक्रेट साठवताना एन्क्रिप्ट केले जातात',
        'enc_on_body' => 'AES-256-GCM सह साठवले जातात, वर्कफ्लोमध्ये आणि डिलिव्हरी रांगेत. वेबहूक URL हे स्वतःच एक क्रेडेन्शियल आहे &mdash; ते ज्याच्याकडे आहे तो तुमच्या चॅनेलवर पोस्ट करू शकतो &mdash; आणि सिग्नेचर सीक्रेट हेच सिद्ध करते की संदेश खरोखर तुमच्याकडून आला आहे.',
        'enc_off_title' => 'कोणतीही एन्क्रिप्शन की कॉन्फिगर केलेली नाही &mdash; वेबहूक URL आणि सिग्नेचर सीक्रेट साध्या मजकुरात साठवले जातात',
        'enc_off_body' => 'एन्क्रिप्शन की फाइल असल्यास FreeITSM हे एन्क्रिप्ट करते, पण या इन्स्टॉलमध्ये ती नाही, म्हणून तुमचे वेबहूक पूर्णपणे अयशस्वी होण्याऐवजी ते जसे आहे तसे जतन केले जात आहेत. डेटाबेस किंवा त्याचा बॅकअप वाचू शकणारा कोणीही तुमच्या चॅनेलवर पोस्ट करू शकतो आणि तुमच्या सिग्नेचर खोट्या बनवू शकतो. एन्क्रिप्शन की (<code>ENCRYPTION_KEY_PATH</code>) कॉन्फिगर करा आणि साठवलेली मूल्ये एन्क्रिप्ट करण्यासाठी प्रत्येक वेबहूक वर्कफ्लो पुन्हा जतन करा.',
        'ret_label' => 'पाठवलेले पेलोड किती काळ ठेवायचे',
        'ret_none' => 'अजिबात साठवू नका',
        'ret_1' => '1 दिवस',
        'ret_7' => '7 दिवस (शिफारस केलेले)',
        'ret_30' => '30 दिवस',
        'ret_forever' => 'डिलिव्हरी नोंद राहील तोपर्यंत',
        'ret_help' => 'डिलिव्हरी नोंद पाठवलेले अचूक पेलोड साठवते. <strong>संपूर्ण नोंद</strong> फॉरमॅटसह तो <strong>संपूर्ण तिकीट</strong> असतो &mdash; विषय, विनंती करणारा, सर्वकाही &mdash; येथे साध्या मजकुरात कॉपी केलेले. इतक्या दिवसांनंतर पेलोड आणि प्रतिसाद मजकूर पुसला जातो, तर डिलिव्हरी <em>नोंद</em> (एंडपॉइंट, स्थिती, वेळ, त्रुटी) वरील नोंद कालावधी ({days} दिवस) ती ओळ पूर्णपणे काढेपर्यंत ऑडिटसाठी ठेवली जाते.',
        'ret_tradeoff' => '<strong>तडजोड:</strong> <em>पुन्हा पाठवा</em> साठवलेले पेलोड पुन्हा पाठवते, त्यामुळे ज्याचे पेलोड पुसले गेले आहे ती डिलिव्हरी पुन्हा पाठवता येत नाही. पुन्हा पाठवणे सहसा अपयशानंतर काही तासांत केले जाते, आठवड्यांनी नाही.',
