    'bingo' => [
        'heading' => 'फीचर बिंगो',
        'intro' => 'बहुतेक लोक त्यांच्याकडे असलेल्या गोष्टींचा थोडाच भाग वापरतात. प्रत्येक कार्ड म्हणजे FreeITSM जे करू शकते अशी एक गोष्ट, आणि येथे सेट केल्यावर त्याचा तारा उजळतो. ती काय आहे, करणे का फायदेशीर आहे आणि कुठे सेट करायची ते पाहण्यासाठी एक उघडा. जे तुम्ही कधीही वापरणार नाही: ते आमच्यासाठी नाही म्हणून चिन्हांकित करा आणि ते गुणांमधून वगळले जाईल.',
