        'import_zeros_html' => '<strong>सुरुवातीचे शून्य:</strong> तुम्ही CSV Excel मध्ये उघडून पुन्हा जतन केल्यास, फाइल FreeITSM पर्यंत पोहोचण्याआधीच Excel 0010 चे 10 करते. तुमची यादी संपादित करण्यासाठी Excel निर्यात (.xlsx) वापरा - त्यातील कोड मजकूर म्हणून साठवले जातात, त्यामुळे शून्य टिकतात.',
